declare(strict_types=1);ini_set('session.save_path',__DIR__.'/../includes/runtime');set_time_limit(0);require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/gemini_transport.php';if(PHP_SAPI!=='cli')exit(1);
$file=__DIR__.'/data/grade8-buddhism-lessons1-3.json';$rows=db()->query("SELECT display_order,title_si,short_description_si,short_notes_si,content_si,learning_objectives_si,key_terms_si,examples_si,summary_si FROM lessons WHERE subject_id=40 AND medium='Sinhala' AND status='active' AND display_order IN(1,2,3) ORDER BY display_order")->fetch_all(MYSQLI_ASSOC);if(count($rows)!==3)throw new RuntimeException('Grade 8 Buddhism lessons 1-3 were not found.');$focus=[1=>'දේවදත්ත හිමියන්ගේ පංචවරය; කාන්තා පැවිද්ද හා අෂ්ට ගරු ධර්ම; චුල්ලපන්ථක හිමි; නන්ද හිමි; දැහැමි ගැටලු විසඳීම',2=>'සුහදශීලී කතාබහ; ආගන්තුක සත්කාරය; මහජන මතයට ගරු කිරීම; අල්පශබ්දතාව; නිහතමානී බව',3=>'තුනුරුවන්ගේ ගුණ 24 සහ දහම් ගුණ හය: ස්වාක්ඛාත, සන්දිට්ඨික, අකාලික, ඒහිපස්සික, ඕපනයික, පච්චත්තං වේදිතබ්බෝ විඤ්ඤූහි'];$out=[];
