'summary_si'],'questions'=>$questions];if(!is_dir(dirname($file)))mkdir(dirname($file),0775,true);file_put_contents($file,json_encode($out,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));echo "Built lesson $n\n";}
